-- ════════════════════════════════════════════════════════════════════════════
--  Import 1,221 new B2B contacts (international schools, student
--  associations, university surf/sport clubs) into outreach_contacts.
--  Source: Gota_Dagua_CRM_FULL_master.csv (NO rows only — the YES
--  rows are the 628 already in the CRM, untouched).
--
--  Idempotent: a UNIQUE index on lower(email) + ON CONFLICT DO NOTHING
--  means re-running the script never duplicates rows; only fills in
--  whatever was missing.
-- ════════════════════════════════════════════════════════════════════════════

-- 1) Unique constraint on lowercased email (skipping NULLs).
create unique index if not exists outreach_contacts_email_uidx
  on public.outreach_contacts (lower(email)) where email is not null;

-- 2) Insert the 1,221 new rows. Existing emails are skipped silently.
on conflict (lower(email)) do nothing;

-- 3) Verify
select count(*) as total_contacts from public.outreach_contacts;
--  Expected ~1849 (628 existing + up to 1221 new — minus 9 emails that
--  already overlapped per the brief).
select segment, count(*) from public.outreach_contacts group by segment order by count(*) desc;
